<script setup>
import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { getAdminCourse, getAdminClasses } from "../../services/adminRepository";
const route=useRoute(),course=ref(null),classes=ref([]),loading=ref(true),error=ref(""); async function load(){try{course.value=await getAdminCourse(route.params.courseId);const r=await getAdminClasses({course_id:route.params.courseId});classes.value=r.items||[]}catch(e){error.value=e.response?.data?.detail||e.message||"加载失败"}finally{loading.value=false}} onMounted(load);
</script>
<template><main class="portal-page admin-portal page-enter"><div v-if="loading" class="portal-loading"><i></i></div><div v-else-if="error" class="portal-error">{{error}}</div><template v-else><div class="portal-heading"><div><span class="portal-kicker">课程详情</span><h1>{{course.name}}</h1><p>{{course.code||'暂无代码'}} · {{course.semester||'未设置学期'}} · {{course.teacher_name||'未分配教师'}}</p></div></div><section class="metric-strip admin-metrics"><button><span>课程状态</span><strong>{{course.status}}</strong></button><button><span>班级数量</span><strong>{{classes.length}}</strong></button></section><section class="portal-panel account-table"><div class="portal-section-title"><h2>教学班</h2></div><div class="account-head"><span>班级</span><span>班级代码</span><span>容量</span><span>邀请码</span></div><article v-for="item in classes" :key="item.id" class="account-row"><strong>{{item.name}}</strong><span>{{item.class_code||'—'}}</span><span>{{item.capacity||'不限'}}</span><span>{{item.invite_code}}</span></article><div v-if="!classes.length" class="portal-empty">暂无班级数据</div></section></template></main></template>
